import React, { useCallback, useRef, useState } from 'react';
import { Button, CircularProgress } from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';

type Props = {
  containerRef: React.RefObject<HTMLElement | null>;
  filename?: string;
  label?: string;
};

const ChartExportButton: React.FC<Props> = ({
  containerRef,
  filename = 'carbon-chart.png',
  label = 'Export chart PNG',
}) => {
  const [exporting, setExporting] = useState(false);
  const fallbackCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const exportPng = useCallback(async () => {
    const container = containerRef.current;
    if (!container) {
      return;
    }
    setExporting(true);
    try {
      const svg = container.querySelector('svg');
      if (!svg) {
        throw new Error('No chart SVG found');
      }

      const serializer = new XMLSerializer();
      const svgString = serializer.serializeToString(svg);
      const svgBlob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(svgBlob);

      const img = new Image();
      const canvas = fallbackCanvasRef.current || document.createElement('canvas');
      const bbox = svg.getBoundingClientRect();
      canvas.width = Math.max(1, Math.floor(bbox.width));
      canvas.height = Math.max(1, Math.floor(bbox.height));

      await new Promise<void>((resolve, reject) => {
        img.onload = () => {
          const ctx = canvas.getContext('2d');
          if (!ctx) {
            reject(new Error('Canvas unavailable'));
            return;
          }
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0);
          URL.revokeObjectURL(url);
          resolve();
        };
        img.onerror = () => reject(new Error('Failed to render chart SVG'));
        img.src = url;
      });

      canvas.toBlob((blob) => {
        if (!blob) return;
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = filename;
        link.click();
        URL.revokeObjectURL(link.href);
      }, 'image/png');
    } finally {
      setExporting(false);
    }
  }, [containerRef, filename]);

  return (
    <>
      <canvas ref={fallbackCanvasRef} style={{ display: 'none' }} aria-hidden />
      <Button
        size="small"
        variant="outlined"
        startIcon={exporting ? <CircularProgress size={14} /> : <DownloadIcon />}
        onClick={exportPng}
        disabled={exporting}
        aria-label={label}
      >
        {label}
      </Button>
    </>
  );
};

export default ChartExportButton;
